{
  "$schema": "https://vega.github.io/schema/vega-lite/v6.json",
  "width": 470, "height": 220,
  "title": "Calories per 100 g (orange = brushed in scatter)",
  "mark": {"type": "point", "filled": true, "size": 70},
  "encoding": {
    "x": {"field": "cal_per_100g", "type": "quantitative", "title": "Calories per 100 g"},
    "y": {"field": "restaurant", "type": "nominal", "title": null},
    "color": {"condition": {"test": "datum.interacted === '1'", "value": "#e6550d"}, "value": "#9a9a9a"},
    "tooltip": [{"field": "item"}, {"field": "cal_per_100g", "format": ".0f"}]
  }
}
